        {
            std::vector<bool> s;
            std::vector<string> names; names.push_back("Wolf"); names.push_back("Katilda");
            CHECK(parseAttackerSet("ATTACK: A1>W1, A2", 2, s, &names) == 2 && s[0] && s[1],
                  "#W64-AI F4 the A-set parse is unchanged by the >W# suffix");
        }
