        CHECK(xLibraryCeilingX(20, 1, 14, xLibraryReserveCount(1, 0)) == 13
                  && xLibraryCeilingX(20, 1, 14, xLibraryReserveCount(1, 2)) == 11,
              "#W67-AZ R5 the ceiling still folds the undeclinable draws, and only those");
